// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(value <= address(c).balance);
        vm.assume(target != address(0));
        vm.assume(target != address(c));

        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();

        if (msg.sender == c.owner()) {
            c.sendMoney(target, value);
        } else {
            vm.prank(c.owner());
            c.sendMoney(target, value);
        }

        uint256 balanceAfter = address(c).balance;
        uint256 depositsAfter = c.depositsCount();

        // The contract's balance plus the sum of all deposits (which equals the number of receive calls) should not increase beyond initial plus sent value
        assertTrue(balanceAfter + depositsAfter <= balanceBefore + depositsBefore + value);
    }
}

